import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen0Test {







    @Test
    public void testIsNumber_ScientificNotation() {
        assertTrue(NumberUtils.isNumber("1e10"));
        assertTrue(NumberUtils.isNumber("1E10"));
        assertTrue(NumberUtils.isNumber("1.2e-5"));
        assertTrue(NumberUtils.isNumber("1.2E+5"));
        assertFalse(NumberUtils.isNumber("e10"));
        assertFalse(NumberUtils.isNumber("1e"));
        assertFalse(NumberUtils.isNumber("1e1.2")); // decimal in exponent not allowed by logic
        assertFalse(NumberUtils.isNumber("1e1e1"));
        assertFalse(NumberUtils.isNumber("1e+"));
        assertFalse(NumberUtils.isNumber("1e-"));
    }












}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen0Test {









    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue(NumberUtils.isNumber("0x123"));
        assertTrue(NumberUtils.isNumber("0xABC"));
        assertTrue(NumberUtils.isNumber("0xabc"));
        assertTrue(NumberUtils.isNumber("0x1a2B3c"));
        assertFalse(NumberUtils.isNumber("0x"));
        assertFalse(NumberUtils.isNumber("-0x123")); // Code handles sign at start, then checks 0x
        // Note: Based on implementation, -0x123 would check if chars[0] == '-' -> start=1. 
        // Then chars[1]=='0' && chars[2]=='x' -> hex loop. 
        // Let's verify: if str="-0x1", start=1, sz=4. chars[1]='0', chars[2]='x'. i=3. chars[3]='1'. returns true.
        assertTrue(NumberUtils.isNumber("-0x123"));
        assertFalse(NumberUtils.isNumber("0xG"));
    }










}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen0Test {











    @Test
    public void testIsNumber_TypeQualifiers() {
        // Test d, D, f, F
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123f"));
        assertTrue(NumberUtils.isNumber("123F"));
        // Test l, L
        assertTrue(NumberUtils.isNumber("123l"));
        assertTrue(NumberUtils.isNumber("123L"));
        // L/l with exponent is not allowed per code: return foundDigit && !hasExp;
        assertFalse(NumberUtils.isNumber("123e10l"));
        assertFalse(NumberUtils.isNumber("123e10L"));

        // Test invalid qualifiers
        assertFalse(NumberUtils.isNumber("123x"));
        assertFalse(NumberUtils.isNumber("123.f")); // dot + f is handled by the last char logic
        // In the code: if chars[i] == '.' and hasDecPoint/hasExp -> false. 
        // If chars[i] is 'f', it checks foundDigit.
    }








}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen0Test {













    @Test
    public void testIsNumber_EdgeCasesAndInvalid() {
        assertFalse(NumberUtils.isNumber("abc"));
        assertFalse(NumberUtils.isNumber("12a3"));
        assertFalse(NumberUtils.isNumber(" "));
        assertFalse(NumberUtils.isNumber("12 3"));
        assertFalse(NumberUtils.isNumber("+-123"));
        assertFalse(NumberUtils.isNumber("1e+-123"));
        assertFalse(NumberUtils.isNumber("1.2e1.2"));
        assertFalse(NumberUtils.isNumber("1.2.3"));

        // Test the 'allowSigns' logic for trailing E
        // The code loops until sz-1. If it ends in 'e' or 'E', the loop might exit.
        // "123E" -> sz=4, start=0. i goes 0, 1, 2. 
        // i=0 (1), i=1 (2), i=2 (3), i=3 (E). 
        // But loop condition is i < sz (where sz is length-1).
        // Let's trace "123E": sz=4. chars=['1','2','3','E']. 
        // start=0. sz becomes 3. 
        // i=0: '1' (foundDigit=true, allowSigns=false). i=1.
        // i=1: '2' (foundDigit=true, allowSigns=false). i=2.
        // i=2: '3' (foundDigit=true, allowSigns=false). i=3.
        // Loop ends because i=3 is not < sz(3).
        // i < chars.length (3 < 4) is true.
        // chars[3] is 'E'. 
        // if (chars[i] == 'e' || chars[i] == 'E') returns false. Correct.
        assertFalse(NumberUtils.isNumber("123E"));
        assertFalse(NumberUtils.isNumber("123e"));
    }






}

