public class NumberUtils_isNumber_TriageGen0Test {



















    @Test
    public void testIsNumber_SpecificBranchCoverage() {
        // Test the 'allowSigns' and 'foundDigit' loop extension
        // while (i < sz || (i < sz + 1 && allowSigns && !foundDigit))
        // This part handles cases where a sign follows an 'E' but no digit is found yet.
        // If input is "1E-", it should return false.
        assertFalse(NumberUtils.isNumber("1E-"));

        // Test the hex logic specifically for "0x"
        assertFalse(NumberUtils.isNumber("0x"));
    }
